@php($images=json_decode($product->images,true)?:[])<div class="grid gap-8 lg:grid-cols-2"><div x-data="{active:0}" class="space-y-3"><div class="aspect-square overflow-hidden rounded-3xl border bg-white">@foreach($images as $i=>$img)<img x-show="active==={{ $i }}" src="{{ asset('storage/'.$img) }}" alt="{{ $product->name }}" class="h-full w-full object-cover">@endforeach</div>@if(count($images)>1)<div class="grid grid-cols-5 gap-2">@foreach($images as $i=>$img)<button @click="active={{ $i }}" class="aspect-square overflow-hidden rounded-xl border bg-white"><img src="{{ asset('storage/'.$img) }}" class="h-full w-full object-cover"></button>@endforeach</div>@endif</div><div class="flex flex-col justify-center"><p class="text-sm font-semibold text-orange-600">{{ $product->category?->name }}</p><h1 class="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">{{ $product->name }}</h1><p class="mt-4 text-3xl font-bold">₱{{ number_format($product->price,2) }}</p><p class="mt-4 leading-relaxed text-zinc-600">{{ $product->description }}</p><div class="mt-6 flex items-center gap-3"><button wire:click="decrement" class="h-10 w-10 rounded-xl border bg-white">−</button><span class="min-w-10 text-center font-semibold">{{ $quantity }}</span><button wire:click="increment" class="h-10 w-10 rounded-xl border bg-white">+</button><span class="ml-2 text-sm text-zinc-500">{{ $product->stock }} available</span></div><button wire:click="addToCart" @disabled($product->stock<1) class="mt-6 rounded-xl bg-orange-500 px-5 py-3.5 font-semibold text-white disabled:bg-zinc-300">{{ $product->stock>0?'Add to cart':'Out of stock' }}</button></div></div>
